package main
import "fmt"

func processar() {
    defer fmt.Println("3. Fim da função (defer)")

    // Slice dinâmico e Map chave-valor
    nums := []int{10, 20}
    nums = append(nums, 30)
    idades := map[string]int{"Ana": 25}

    // O único loop do Go (com range)
    for idx, val := range nums {
        fmt.Println(idx, val, idades["Ana"])
    }
}

